import React, { useState, useEffect } from 'react';
import SearchBar from '../SearchBar/SearchBar';
import SearchResults from '../SearchResults/SearchResults';
import Playlist from '../Playlist/Playlist';
import { search, createPlaylist } from "../../utils/spotifyApi";
import { getAccessToken } from "../../hooks/useSpotifyAuth";

let hasFetchedToken = false;

export default function App() {
  const [searchResults, setSearchResults] = useState([]);
  const [playlistName, setPlaylistName] = useState("New Playlist");
  const [playlistTracks, setPlaylistTracks] = useState([]);
  const [editing, setEditing] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  useEffect(() => {
    if (!hasFetchedToken) {
      hasFetchedToken = true;
      getAccessToken();
    }
  }, []);

  async function handleSearch(term) {
    setHasSearched(true);
    const results = await search(term);
    setSearchResults(results);
  }

  function addTrack(track) {
    if (!playlistTracks.find(t => t.id === track.id)) {
      setPlaylistTracks(prev => [...prev, track]);
    }
  }

  function removeTrack(track) {
    setPlaylistTracks(prev => prev.filter(t => t.id !== track.id));
  }

  async function savePlaylist() {
    if (!playlistTracks.length) {
      console.log("No tracks to save.");
      return;
    }

    const trackUris = playlistTracks.map(track => track.uri);
    console.log("Saving playlist with URIs:", trackUris);

    try {
      const playlist = await createPlaylist(playlistName, trackUris);

      if (!playlist || !playlist.id) {
        console.error("Playlist creation failed:", playlist);
        return;
      }

      console.log("Playlist saved successfully!", playlist);

      // Reset playlist UI
      setPlaylistName("New Playlist");
      setPlaylistTracks([]);

    } catch (error) {
      console.error("Error saving playlist:", error);
    }
  }


  return (
    <div className="App">
      <h1>Jammming</h1>
      <h2>(Spotify Edition)</h2>
      <SearchBar 
        onSearch={handleSearch} 
        editing={editing}
      />
      <SearchResults 
        searchResults={searchResults} 
        onAddTrack={addTrack}
        editing={editing}
        hasSearched={hasSearched}
      />
      <Playlist
        playlistName={playlistName}
        playlistTracks={playlistTracks}
        onNameChange={setPlaylistName}
        onAddTrack={addTrack}
        onRemoveTrack={removeTrack}
        onSave={savePlaylist}
        editing={editing}
        setEditing={setEditing}
      />
    </div>
  );
}

// src/components/Playlist/Playlist.jsx
import React, { useState } from 'react';
import Tracklist from '../Tracklist/Tracklist';

export default function Playlist({
    playlistName,
    playlistTracks,
    onNameChange,
    onAddTrack,
    onRemoveTrack,
    onSave,
    editing,
    setEditing
  }) {

  return (
    <div className="Playlist">
      {editing ? (
        <input
          value={playlistName}
          onChange={(e) => onNameChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              setEditing(false);
            }
          }}
          onBlur={() => setEditing(false)}
          autoFocus
        />
      ) : (
        <h2 onClick={() => setEditing(true)}>
          {playlistName}
        </h2>
      )}

      <p>
        {playlistTracks.length} {playlistTracks.length === 1 ? "track" : "tracks"}
      </p>

      <Tracklist
        tracks={playlistTracks}
        onAddTrack={onAddTrack}
        onRemoveTrack={onRemoveTrack}
        editing={editing}
      />

      <button onClick={onSave}>
        Save to Spotify
      </button>
    </div>
  );
}

// src/components/SearchBar/SearchBar.jsx
import React from 'react';

export default function SearchBar({ onSearch, editing }) {
  const [term, setTerm] = React.useState('');

  function handleKeyDown(e) {
    if (e.key === 'Enter' && !editing) {
      onSearch(term);
    }
  }

  return (
    <div className="SearchBar">
      <input
        placeholder="Enter a song, album, or artist"
        value={term}
        onChange={(e) => setTerm(e.target.value)}
        onKeyDown={handleKeyDown}
        disabled={editing}
      />
      <button onClick={() => onSearch(term)} disabled={editing}>
        Search
      </button>
    </div>
  );
}

// src/components/SearchResults/SearchResults.jsx
import React from 'react';
import Tracklist from '../Tracklist/Tracklist';

export default function SearchResults({ searchResults, onAddTrack, editing, hasSearched }) {
  const noResults = hasSearched && searchResults.length === 0;

  return (
    <div className="SearchResults">
      <h2>Results</h2>

      {noResults ? (
        <p className="no-results">No search results meet the search criteria</p>
      ) : (
        <Tracklist 
          tracks={searchResults} 
          onAddTrack={onAddTrack} 
          editing={editing}
        />
      )}
    </div>
  );
}

// src/components/Track/Track.jsx
import React from 'react';

export default function Track({ track, onAddTrack, onRemoveTrack, editing }) {
  return (
    <div className="Track">
      <h3>{track.name}</h3>
      <p>{track.artist} — {track.album}</p>

      {onAddTrack && (
        <button onClick={() => onAddTrack(track)} disabled={editing}>
          +
        </button>
      )}

      {onRemoveTrack && (
        <button onClick={() => onRemoveTrack(track)} disabled={editing}>
          -
        </button>
      )}
    </div>
  );
}

// src/components/Tracklist/Tracklist.jsx
import React from 'react';
import Track from '../Track/Track';

export default function Tracklist({ tracks, onAddTrack, onRemoveTrack, editing }) {
  return (
    <div className="Tracklist">
      {tracks.map(track => (
        <Track
          key={track.id}
          track={track}
          onAddTrack={onAddTrack}
          onRemoveTrack={onRemoveTrack}
          editing={editing}
        />
      ))}
    </div>
  );
}

// --- PKCE HELPERS ---
const generateRandomString = (length) => {
  const possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const values = window.crypto.getRandomValues(new Uint8Array(length));
  return values.reduce((acc, x) => acc + possible[x % possible.length], "");
}

const sha256 = async (plain) => {
  const encoder = new TextEncoder()
  const data = encoder.encode(plain)
  return window.crypto.subtle.digest('SHA-256', data)
}

const base64encode = (input) => {
  return btoa(String.fromCharCode(...new Uint8Array(input)))
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

// --- MAIN AUTH FUNCTION ---

export async function getAccessToken() {
  
  // --- SPOTIFY AUTH CONFIG ---
  const clientId = import.meta.env.VITE_SPOTIFY_CLIENT_ID;
  const redirectUri = import.meta.env.VITE_SPOTIFY_REDIRECT_URI;

  let codeVerifier = localStorage.getItem('code_verifier');

  if (!codeVerifier) {
    codeVerifier = generateRandomString(64);
    localStorage.setItem('code_verifier', codeVerifier);
  }

  const hashed = await sha256(codeVerifier)
  const codeChallenge = base64encode(hashed);

  const scope = 'playlist-modify-public playlist-modify-private';
  const authUrl = new URL("https://accounts.spotify.com/authorize")

  // window.localStorage.setItem('code_verifier', codeVerifier);

  const params =  {
    response_type: 'code',
    client_id: clientId,
    scope,
    code_challenge_method: 'S256',
    code_challenge: codeChallenge,
    redirect_uri: redirectUri,
  }

  authUrl.search = new URLSearchParams(params).toString();
 
  // Parse the URL to retrieve the code parameter
  const urlParams = new URLSearchParams(window.location.search);
  let code = urlParams.get("code");

  if (!code) {
    window.location.href = authUrl.toString();
    return; // prevent running the rest
  }
 
  const getToken = async code => {

    // stored in the previous step
    const codeVerifier = localStorage.getItem('code_verifier');

    const url = "https://accounts.spotify.com/api/token";
    const payload = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        client_id: clientId,
        grant_type: 'authorization_code',
        code,
        redirect_uri: redirectUri,
        code_verifier: codeVerifier,
      }),
    }

    const body = await fetch(url, payload);
    const response = await body.json();

    localStorage.setItem('access_token', response.access_token);
    window.history.replaceState({}, document.title, redirectUri);

  }

  await getToken(code);

  const storedToken = localStorage.getItem('access_token');
  if (storedToken) {
    return storedToken;
  }
  
}

export async function search(term) {
  const cleaned = term.trim();
  if (!cleaned) return [];

  let token = localStorage.getItem('access_token');
  
  const encoded = encodeURIComponent(cleaned);
  
  const response = await fetch(`https://api.spotify.com/v1/search?q=${encoded}&type=track`, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    }
  );

  const data = await response.json();
  console.log("Search Results:", data);
  const tracks = data.tracks?.items || [];

  return tracks.map(track => ({
    id: track.id,
    name: track.name,
    artist: track.artists[0].name,
    album: track.album.name,
    uri: track.uri,
  }));
}

export async function createPlaylist(name, trackUris) {
  let token = localStorage.getItem('access_token');

  // Get user profile
  const profileRes = await fetch("https://api.spotify.com/v1/me", {
    headers: { Authorization: `Bearer ${token}` },
  });
  const profile = await profileRes.json();
  console.log("User Profile:", profile);

  // Create playlist
  const playlistRes = await fetch(
    `https://api.spotify.com/v1/me/playlists`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        name: name,
        description: "Created with Jammming",
      }),
    }
  );

  const playlist = await playlistRes.json();
  console.log("Created Playlist:", playlist);

  // Add tracks
  await fetch(
    `https://api.spotify.com/v1/playlists/${playlist.id}/items`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        uris: trackUris,
      }),
    }
  );

  return playlist;
}
